protocol Vehicle { func drive() -> String }
struct Car: Vehicle { func drive() -> String { "Driving car" } }
struct Bike: Vehicle { func drive() -> String { "Riding bike" } }
enum VehicleFactory {
    static func create(wheels: Int) -> Vehicle { wheels == 2 ? Bike() : Car() }
}
let v = VehicleFactory.create(wheels: 2)
print(v.drive())

struct OldAudioPlayer {
    func playWavFile(name: String) -> String { "Playing wav: \(name)" }
}
protocol AudioPlayer { func play(sound: String) -> String }
struct AudioAdapter: AudioPlayer {
    let oldPlayer: OldAudioPlayer
    func play(sound: String) -> String { oldPlayer.playWavFile(name: sound) }
}
let player = AudioAdapter(oldPlayer: OldAudioPlayer())
print(player.play(sound: "intro.wav"))

protocol TaxStrategy { func computeTax(amount: Double) -> Double }
struct StandardTax: TaxStrategy { func computeTax(amount: Double) -> Double { amount * 0.20 } }
struct ZeroTax: TaxStrategy { func computeTax(amount: Double) -> Double { 0.0 } }
final class TaxCalculator {
    let strategy: TaxStrategy
    init(strategy: TaxStrategy) { self.strategy = strategy }
}
let calc = TaxCalculator(strategy: StandardTax())
print(Int(calc.strategy.computeTax(amount: 100)))

protocol Observer: AnyObject { func notify(message: String) }
final class ConsoleObserver: Observer {
    var lastMessage = ""
    func notify(message: String) { lastMessage = message }
}
final class Broadcaster {
    var observers: [Observer] = []
    func addObserver(_ o: Observer) { observers.append(o) }
    func publish(_ msg: String) { observers.forEach { $0.notify(message: msg) } }
}
let b = Broadcaster()
let o = ConsoleObserver()
b.addObserver(o)
b.publish("Ping")
print(o.lastMessage)

