struct Request { let method: String; let path: String }
final class RequestBuilder {
    private var method = "GET"
    private var path = "/"
    func setMethod(_ m: String) -> RequestBuilder { method = m; return self }
    func setPath(_ p: String) -> RequestBuilder { path = p; return self }
    func build() -> Request { Request(method: method, path: path) }
}
let req = RequestBuilder().setMethod("POST").setPath("/login").build()
print("\(req.method) \(req.path)")

